// This is a TEMPLATE only. The real copy, generated by `bash bin/setup.sh`
// from the project root, is named config.js in this same folder — it is not
// tracked by git (see .gitignore) because it holds deployment-specific
// values (coordinates, board name...).

// Name shown in page titles and the header (in both languages it's still
// prefixed by the translated label, e.g. "Bacheca dal vivo — {MCA_BOARD_NAME}"
// / "Live Board — {MCA_BOARD_NAME}").
const MCA_BOARD_NAME = 'Your Neighborhood';

// Map center: [latitude, longitude]. To find your neighborhood's
// coordinates, open openstreetmap.org, right-click the point you want as
// center → "Show address" reveals lat/lon.
const MCA_MAP_CENTER = [44.395650, 8.654534];

// Initial/preferred map zoom level (Leaflet: higher = closer). 17 shows
// roughly a block or two.
const MCA_MAP_ZOOM = 17;

// Can't zoom out past this level — keeps the map on the neighborhood
// instead of letting it show the whole planet.
const MCA_MAP_MIN_ZOOM = 14;

// Radius (in degrees, not meters) of the box the map can be panned within,
// centered on MCA_MAP_CENTER. 0.012 ≈ 1.3 km.
const MCA_MAP_BOUNDS_RADIUS_DEG = 0.012;

// Beyond this distance (in METERS) from the center, continuous GPS sharing
// stops itself automatically for privacy — it won't share your position if
// you leave the configured neighborhood's "usual area".
const MCA_PRIVACY_RADIUS_METERS = 1500;
